*{box-sizing:border-box} :root{--ink:#080b15;--paper:#e9e9df;--muted:#898e9c;--cyan:#7fffe0;--pink:#ff5e8a;--line:rgba(222,239,239,.13);--mono:'DM Mono',monospace;--display:'Space Grotesk',sans-serif} html,body{margin:0;min-height:100%;background:#080b15;color:var(--paper);font-family:var(--display)}body{min-height:100vh;display:flex;justify-content:center;align-items:center;padding:22px;background-image:radial-gradient(ellipse at 50% 30%,#171d2d 0,#0a0d17 54%,#060810 100%);overflow-x:hidden}.shell{width:min(1200px,100%)}.topbar,.footer{height:44px;display:flex;align-items:center;justify-content:space-between;font:10px var(--mono);letter-spacing:.11em;color:#818694}.brand{font:600 12px var(--display);letter-spacing:.19em;color:#e9e9df;text-decoration:none}.brand-mark{color:var(--cyan);font-size:18px;vertical-align:-2px;margin-right:8px}.brand-divider{color:#424958;margin:0 10px}.brand-sub{font:9px var(--mono);color:#727988}.top-meta{display:flex;align-items:center;gap:10px}.top-meta span:last-child{color:var(--cyan)}.live-dot,.card-status i{width:6px;height:6px;border-radius:50%;background:#8fffe1;box-shadow:0 0 11px #8fffe1;display:inline-block}.sound-toggle{background:none;border:0;color:#a6abba;font:10px var(--mono);letter-spacing:.1em;cursor:pointer}.sound-toggle span{margin-left:5px}.game-frame{position:relative;width:100%;aspect-ratio:8/5;overflow:hidden;border:1px solid #29303d;background:#0b101a;box-shadow:0 24px 80px #0008,inset 0 0 0 1px #ffffff08}.game-frame canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.scanlines{position:absolute;inset:0;pointer-events:none;opacity:.16;background:repeating-linear-gradient(0deg,transparent 0,transparent 3px,#01040a 4px);mix-blend-mode:multiply}.screen{position:absolute;inset:0;z-index:3}.start-screen{display:flex;align-items:center;justify-content:space-between;padding:8% 10%;background:linear-gradient(90deg,rgba(8,11,21,.96) 0%,rgba(8,11,21,.81) 54%,rgba(8,11,21,.23) 100%)}.start-copy{position:relative;z-index:1}.eyebrow{display:flex;align-items:center;gap:11px;color:var(--cyan);font:10px var(--mono);letter-spacing:.14em}.eyebrow-line{width:30px;height:1px;background:#4b6a6b}.start-copy h1{font-size:clamp(43px,6.6vw,78px);line-height:.87;letter-spacing:-.08em;margin:28px 0 18px;font-weight:600}.start-copy h1 em{font-weight:400;color:#9da3b0;font-style:normal}.title-dot{color:var(--cyan)}.intro{max-width:330px;font-size:14px;line-height:1.55;color:#a3a8b5;margin-bottom:28px}.primary-button{display:flex;align-items:center;justify-content:space-between;gap:30px;padding:0 17px;height:45px;color:#0a1018;background:var(--cyan);border:0;font:600 11px var(--mono);letter-spacing:.08em;cursor:pointer;min-width:190px;transition:transform .2s,background .2s}.primary-button:hover{transform:translateY(-2px);background:#bcffed}.primary-button b{font-size:17px}.start-hint{margin-top:22px;color:#747b89;font:9px var(--mono);letter-spacing:.06em}.start-hint i{font-style:normal;color:var(--cyan);padding:0 5px}.start-side{width:235px;align-self:center;transform:translateY(12px)}.signal-card,.relic-card{position:relative;border:1px solid #ffffff20;background:linear-gradient(140deg,#171d29d9,#10151fc9);padding:17px 18px;margin:12px 0;backdrop-filter:blur(8px)}.card-label,.micro-label{display:block;color:#828a98;font:9px var(--mono);letter-spacing:.13em}.signal-card strong{display:block;font:600 19px/1.05 var(--display);letter-spacing:.04em;margin:19px 0 17px}.card-status{font:9px var(--mono);letter-spacing:.08em;color:#a6b0bd}.card-status i{margin-right:7px}.entity-glyph{position:absolute;right:17px;top:44px;color:#ff708d;font-size:44px;text-shadow:0 0 18px #ff3158;opacity:.72}.relic-card{padding:14px 18px}.relic-shards{display:flex;gap:17px;margin:12px 0 7px}.relic-shards b{font-size:21px;color:#5a6070}.relic-shards b:first-child{color:var(--cyan);text-shadow:0 0 12px #61fcd0}.relic-card>span:last-child{font:8px var(--mono);letter-spacing:.1em;color:#848b99}.footer{height:36px;font-size:9px}.footer b{font-size:14px;color:var(--cyan);margin-left:5px}.hud{position:absolute;inset:0;z-index:2;pointer-events:none}.hud-top{position:absolute;top:0;left:0;right:0;display:grid;grid-template-columns:1fr 1.15fr 1fr;gap:16px;align-items:center;padding:17px 22px 14px;background:linear-gradient(#080b15e8,#080b15a8,transparent)}.world-label{display:flex;align-items:center;gap:10px}.world-index{font:26px var(--mono);color:var(--cyan)}.world-label strong,.objective strong{display:block;font:600 12px var(--display);letter-spacing:.06em;margin-top:3px}.objective{justify-self:center;text-align:center}.objective-progress{display:block;margin-top:5px;color:var(--cyan);font:9px var(--mono);min-height:11px}.health-block{justify-self:end}.hearts{display:flex;gap:5px;margin-top:5px;color:#ff6e8f;font-size:16px}.heart-empty{color:#434550}.hud-bottom{position:absolute;bottom:0;left:0;right:0;padding:16px 22px;display:flex;align-items:flex-end;justify-content:space-between;background:linear-gradient(transparent,#080b15c4 48%,#080b15e8)}.relic-status{display:flex;align-items:center;gap:7px;font:11px var(--mono);color:#c7ccd4}.relic-icon{color:var(--cyan);font-size:19px}.relic-status .micro-label{font-size:8px;margin-left:4px}.relic-pips{display:flex;gap:4px;margin-left:4px}.relic-pips i{width:8px;height:8px;border:1px solid #697181;transform:rotate(45deg)}.relic-pips i.filled{background:var(--cyan);border-color:var(--cyan);box-shadow:0 0 8px #7fffe077}.controls-hint{font:8px var(--mono);color:#9298a5;letter-spacing:.04em}.controls-hint kbd{font:8px var(--mono);color:#e7eaf0;border:1px solid #7d8490;padding:3px 4px;margin-left:9px}.controls-hint kbd:first-child{margin-left:0}.boss-bar{position:absolute;bottom:48px;left:50%;transform:translateX(-50%);width:min(340px,40%)}.boss-heading{display:flex;justify-content:space-between;margin-bottom:6px;font:9px var(--mono);letter-spacing:.06em}.boss-heading b{color:#ff788e;font-weight:400}.boss-track{height:6px;background:#272a35;border:1px solid #5b3542}.boss-track i{height:100%;display:block;width:100%;background:linear-gradient(90deg,#ff315e,#ff8e69);transition:width .25s}.toast{position:absolute;top:27%;left:50%;transform:translateX(-50%);padding:10px 15px;border:1px solid #7fffe088;background:#08121bdc;color:var(--cyan);font:10px var(--mono);letter-spacing:.1em;white-space:nowrap;box-shadow:0 0 22px #00f5b322}.hidden{display:none!important}.pause-screen,.end-screen{background:#070a12dd;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(5px)}.pause-panel,.end-content{width:min(430px,82%);padding:30px;border:1px solid #48505c;background:#0d121d}.pause-panel h2,.end-content h2{font-size:34px;letter-spacing:-.06em;margin:20px 0 8px}.pause-panel p,.end-content p{color:#a7adba;line-height:1.6;font-size:13px;margin:0 0 24px}.text-button{display:block;margin-top:16px;padding:0;border:0;background:none;color:#a3aaba;font:9px var(--mono);letter-spacing:.1em;cursor:pointer}.end-content{position:relative}.end-content .eyebrow{margin-bottom:20px}.end-content blockquote{margin:20px 0;color:#ffd2da;font-size:16px;line-height:1.5}.end-content .secret{color:var(--cyan);font:12px var(--mono);line-height:1.7}.end-content .primary-button{margin-top:22px}.mobile-controls{position:absolute;z-index:4;bottom:68px;left:18px;right:18px;justify-content:space-between;align-items:flex-end;pointer-events:none}.mobile-controls button{pointer-events:auto;color:#e6fff8;border:1px solid #b5fff677;background:#0b1720aa;touch-action:none}.dpad>button{display:block;margin:0 auto 4px;width:42px;height:35px}.dpad div{display:flex;gap:4px}.dpad div button{width:42px;height:35px}.action-pad{display:flex;align-items:flex-end;gap:10px}.action-pad button{height:55px;width:55px;border-radius:50%;font:10px var(--mono)}.action-pad #mobile-attack{width:68px;height:68px;color:#081017;background:#7fffe0;font-size:24px}.end-screen .end-content{animation:appear .5s ease}@keyframes appear{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:700px){body{padding:8px;align-items:flex-start}.shell{margin-top:8px}.topbar{height:35px}.brand{font-size:10px}.brand-sub{display:none}.top-meta{font-size:8px;gap:6px}.sound-toggle{font-size:0}.sound-toggle span{font-size:8px}.game-frame{aspect-ratio:3/4;max-height:calc(100dvh - 92px)}.game-frame canvas{object-fit:cover}.start-screen{padding:9% 8%;align-items:flex-start;background:linear-gradient(100deg,#080b15f5,#080b15b5 70%,#080b1544);flex-direction:column}.start-copy h1{font-size:clamp(40px,11vw,62px);margin:18px 0 12px}.intro{font-size:12px;max-width:270px;margin:0 0 17px}.start-hint{font-size:7px;max-width:280px;line-height:1.7;margin-top:14px}.start-side{display:flex;gap:8px;width:100%;margin-top:auto;transform:none}.signal-card,.relic-card{flex:1;padding:10px}.signal-card strong{font-size:15px;margin:9px 0}.entity-glyph{font-size:30px;right:9px;top:28px}.card-status,.card-label,.relic-card>span:last-child{font-size:7px}.relic-shards{gap:9px;margin:7px 0}.hud-top{padding:12px 12px 10px;grid-template-columns:1fr 1.2fr 1fr;gap:5px}.world-index{font-size:19px}.world-label{gap:5px}.world-label strong,.objective strong{font-size:9px}.micro-label{font-size:7px}.objective-progress{font-size:7px}.hearts{font-size:12px;gap:2px}.hud-bottom{padding:10px 12px 13px}.controls-hint{display:none}.relic-status{font-size:9px;gap:4px}.relic-pips i{width:6px;height:6px}.boss-bar{width:50%;bottom:42px}.boss-heading{font-size:7px}.mobile-controls{display:flex}.footer{height:28px;font-size:7px}.footer span:nth-child(2){display:none}.toast{top:26%;font-size:8px}.pause-panel,.end-content{padding:22px}.pause-panel h2,.end-content h2{font-size:28px}}
@media(max-height:700px) and (min-width:701px){body{padding-top:8px;padding-bottom:8px}.topbar{height:32px}.footer{height:27px}.game-frame{max-height:calc(100vh - 70px)}}

(() => {
  'use strict';
  const canvas = document.getElementById('game'), ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const $ = id => document.getElementById(id);
  const screens = { start: $('start-screen'), pause: $('pause-screen'), end: $('end-screen') };
  const worldData = [
    { name:'ABANDONED CITY', objective:'Find the keys', short:'LOCATE 3 ACCESS KEYS', color:'#7fffe0', kind:'city' },
    { name:'DIGITAL NIGHTMARE', objective:'Defeat the glitches', short:'PURGE THE GLITCHES', color:'#cf81ff', kind:'digital' },
    { name:'FORGOTTEN DESERT', objective:'Find the artifact', short:'RECOVER THE ARTIFACT', color:'#ffce82', kind:'desert' },
    { name:'COSMIC ABYSS', objective:'Open the portal', short:'ALIGN 3 PORTAL NODES', color:'#86a2ff', kind:'cosmic' },
    { name:'CITADEL: ULTITANKIST_RUT', objective:'Defeat the main boss', short:'END THE LOOP', color:'#ff5d7d', kind:'citadel' }
  ];
  const state = { mode:'menu', world:0, relics:0, player:null, enemies:[], pickups:[], obstacles:[], projectiles:[], particles:[], nodes:[], boss:null, time:0, worldTime:0, toast:0, toastText:'', keys:{}, pointer:null, shake:0, sound:false, last:0 };
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y), rand=(a,b)=>a+Math.random()*(b-a);
  const rnd=(n)=>{let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x)};
  function showToast(text){state.toastText=text;state.toast=2.3;$('toast').textContent=text;$('toast').classList.remove('hidden')}
  function startRun(){state.mode='playing';state.world=0;state.relics=0;state.player={x:480,y:495,r:12,hp:5,maxHp:5,speed:210,faceX:0,faceY:-1,attackCd:0,dashCd:0,dashTime:0,invuln:0,trail:[]};screens.start.classList.add('hidden');screens.pause.classList.add('hidden');screens.end.classList.add('hidden');$('hud').classList.remove('hidden');$('mobile-controls').classList.remove('hidden');enterWorld(0)}
  function enterWorld(index){state.world=index;state.worldTime=0;state.enemies=[];state.pickups=[];state.projectiles=[];state.particles=[];state.nodes=[];state.boss=null;state.shake=0;state.player.x=480;state.player.y=500;state.player.hp=Math.min(state.player.maxHp,state.player.hp+1);state.player.invuln=1.2;state.player.attackCd=0;state.player.dashCd=0;state.obstacles=makeObstacles(index);createWorld(index);updateHud();showToast(index===4?'THE CITADEL IS OPEN. FACE YOUR MAKER.':`WORLD ${String(index+1).padStart(2,'0')} // ${worldData[index].name}`)}
  function makeObstacles(index){
    const result=[];const positions=index===0?[[190,180,90,25],[680,220,36,105],[350,340,120,24],[770,430,90,25],[135,420,32,90]]:index===1?[[160,215,100,26],[680,170,28,125],[390,400,140,26],[790,400,28,85],[245,460,80,22]]:index===2?[[210,180,115,22],[680,220,95,24],[340,380,70,26],[770,420,65,24],[480,225,42,42]]:index===3?[[210,200,85,25],[690,180,30,110],[350,390,110,24],[765,425,80,23]]:[[210,180,90,22],[660,180,90,22],[190,415,80,22],[690,415,80,22]];
    for(const [x,y,w,h] of positions)result.push({x,y,w,h});return result;
  }
  function createWorld(index){
    const points=[[240,220],[730,180],[735,390],[250,420],[490,170],[490,430],[365,285],[610,300]];
    if(index===0){points.slice(0,5).forEach((p,i)=>state.pickups.push({x:p[0],y:p[1],type:'key',taken:false,id:i}));addEnemies(3,'drone')}
    if(index===1){addEnemies(7,'glitch')}
    if(index===2){state.pickups.push({x:485,y:300,type:'artifact',taken:false});addEnemies(5,'scarab')}
    if(index===3){for(let i=0;i<3;i++)state.nodes.push({x:points[i][0],y:points[i][1],active:false,phase:i*2}) ;addEnemies(4,'wisp')}
    if(index===4){state.boss={x:480,y:210,hp:300,maxHp:300,phase:0,teleport:2.5,attack:1.4,pattern:0,windup:0,copyTimer:0,copies:[],hitFlash:0,defeated:false};}
  }
  function addEnemies(count,type){const spots=[[160,285],[800,280],[355,185],[590,400],[490,320],[220,365],[720,315],[380,460],[620,220]];for(let i=0;i<count;i++){const p=spots[i%spots.length];state.enemies.push({x:p[0]+rand(-18,18),y:p[1]+rand(-15,15),r:type==='glitch'?13:11,hp:type==='glitch'?2:1,type,phase:rand(0,6),speed:type==='glitch'?56:48,attack:rand(.3,1.3),hurt:0})}}
  function updateHud(){const w=worldData[state.world];$('world-index').textContent=String(state.world+1).padStart(2,'0');$('world-name').textContent=w.name;$('objective-text').textContent=w.objective;$('top-world').textContent=`${String(state.world+1).padStart(2,'0')} / 05`;$('boss-bar').classList.toggle('hidden',state.world!==4);updateRelics();updateObjective()}
  function updateRelics(){$('relic-count').textContent=`${state.relics} / 4`;$('relic-pips').querySelectorAll('i').forEach((el,i)=>el.classList.toggle('filled',i<state.relics));$('hearts').innerHTML=Array.from({length:state.player?state.player.maxHp:5},(_,i)=>`<span class="${state.player&&i<state.player.hp?'':'heart-empty'}">${state.player&&i<state.player.hp?'♥':'♡'}</span>`).join('')}
  function updateObjective(){const w=state.world;let t='';if(w===0)t=`${state.pickups.filter(p=>p.type==='key'&&!p.taken).length} KEYS REMAINING · REACH THE GATE`;if(w===1)t=`${state.enemies.length} GLITCH${state.enemies.length===1?'':'ES'} LEFT`;if(w===2)t=state.pickups.some(p=>p.type==='artifact'&&!p.taken)?'ARTIFACT SIGNAL: ACTIVE':'ARTIFACT RECOVERED · REACH THE GATE';if(w===3)t=`${state.nodes.filter(n=>n.active).length} / 3 NODES ALIGNED`;if(w===4)t=state.boss?`${state.boss.phase===0?'NORMAL':state.boss.phase===1?'GLITCH':'ABSOLUTE'} FORM`:'CITADEL CLEARED';$('objective-progress').textContent=t}

input.newString:
$('objective-progress').textContent=t}
  function completeWorld(){if(state.world<4){state.relics++;updateRelics();showToast(`ANCIENT ARTIFACT FRAGMENT ${state.relics} / 4 ACQUIRED`);setTimeout(()=>enterWorld(state.world+1),1250)}else winGame()}
  function winGame(){state.mode='won';$('mobile-controls').classList.add('hidden');$('boss-bar').classList.add('hidden');$('end-content').innerHTML=`<div class="eyebrow">TRANSMISSION TERMINATED <span class="eyebrow-line"></span> CITADEL FALLEN</div><h2>The loop is broken.</h2><p>ULTITANKIST_RUT has gone quiet. The four fragments are whole again—and somewhere, a new game is beginning.</p><div class="secret">“ULTITANKIST_RUT hasn't finished his game yet...”</div><button class="primary-button" id="again-button"><span>PLAY AGAIN</span><b>↗</b></button>`;$('end-screen').classList.remove('hidden');$('again-button').addEventListener('click',startRun);}
  function loseGame(){state.mode='lost';$('mobile-controls').classList.add('hidden');$('end-content').innerHTML=`<div class="eyebrow">SIGNAL LOST <span class="eyebrow-line"></span> RUN ENDED</div><h2>Not this time.</h2><p>The city is still waiting. The citadel is still listening.</p><button class="primary-button" id="again-button"><span>TRY AGAIN</span><b>↗</b></button>`;$('end-screen').classList.remove('hidden');$('again-button').addEventListener('click',startRun);}
  function pause(){if(state.mode==='playing'){state.mode='paused';screens.pause.classList.remove('hidden')}}function resume(){if(state.mode==='paused'){state.mode='playing';screens.pause.classList.add('hidden');state.last=performance.now()}}
  function attack(){const p=state.player;if(state.mode!=='playing'||p.attackCd>0)return;p.attackCd=.36;spawnBurst(p.x+p.faceX*25,p.y+p.faceY*25,worldData[state.world].color,8);state.shake=Math.max(state.shake,.7);
    for(const e of [...state.enemies])if(Math.hypot(e.x-p.x,e.y-p.y)<62){e.hp--;e.hurt=.2;knock(e,p,22);if(e.hp<=0){spawnBurst(e.x,e.y,worldData[state.world].color,12);state.enemies.splice(state.enemies.indexOf(e),1);if(state.world===1)updateObjective()}}
    const b=state.boss;if(b&&Math.hypot(b.x-p.x,b.y-p.y)<98){const damage=b.phase===1?7:10;b.hp-=damage;b.hitFlash=.15;knock(b,p,20);spawnBurst(b.x,b.y,'#ffb3cf',7);if(b.hp<=0){b.hp=0;b.defeated=true;spawnBurst(b.x,b.y,'#ff667f',55);setTimeout(winGame,1500)}}
  }
  function knock(target,powerSource,amount){const dx=target.x-powerSource.x,dy=target.y-powerSource.y,l=Math.hypot(dx,dy)||1;target.x=clamp(target.x+dx/l*amount,45,W-45);target.y=clamp(target.y+dy/l*amount,55,H-55)}
  function dash(){const p=state.player;if(state.mode!=='playing'||p.dashCd>0)return;p.dashCd=1.05;p.dashTime=.19;p.invuln=Math.max(p.invuln,.31);spawnBurst(p.x,p.y,'#a8fff0',7)}
  function damagePlayer(){const p=state.player;if(p.invuln>0)return;p.hp--;p.invuln=1.15;state.shake=5;spawnBurst(p.x,p.y,'#ff6685',13);updateRelics();if(p.hp<=0)loseGame()}
  function spawnBurst(x,y,color,n){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(25,145);state.particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.22,.6),max:.6,color,size:rand(1.5,4)})}}
  function fireAt(x,y,speed,color,size=6){const p=state.player,dx=p.x-x,dy=p.y-y,l=Math.hypot(dx,dy)||1;state.projectiles.push({x,y,vx:dx/l*speed,vy:dy/l*speed,r:size,color,life:4})}
  function collect(pickup){pickup.taken=true;const c=worldData[state.world].color;spawnBurst(pickup.x,pickup.y,c,20);if(pickup.type==='key'){if(state.pickups.filter(p=>p.type==='key'&&!p.taken).length===0){showToast('ALL KEYS FOUND. THE GATE IS OPEN.');updateObjective()}}if(pickup.type==='artifact'){showToast('THE THIRD FRAGMENT IS YOURS.');updateObjective()}updateObjective()}
  function interact(){if(state.mode!=='playing')return;const p=state.player;if(state.world===3){for(const node of state.nodes)if(!node.active&&dist(p,node)<58){node.active=true;spawnBurst(node.x,node.y,'#93b7ff',22);showToast(`PORTAL NODE ${state.nodes.filter(n=>n.active).length} / 3 ALIGNED`);updateObjective();if(state.nodes.every(n=>n.active))showToast('PORTAL OPEN. ENTER THE LIGHT.');return}}}
  function movePlayer(dt){const p=state.player,k=state.keys;let x=(k.right||k.ArrowRight?1:0)-(k.left||k.ArrowLeft?1:0),y=(k.down||k.ArrowDown?1:0)-(k.up||k.ArrowUp?1:0);if(state.pointer){x+=state.pointer.x;y+=state.pointer.y}const m=Math.hypot(x,y);if(m){x/=m;y/=m;p.faceX=x;p.faceY=y}if(p.dashTime>0){p.dashTime-=dt;x=p.faceX*2.7;y=p.faceY*2.7}else{x*=1;y*=1}const speed=p.speed*(p.dashTime>0?2.7:1);let nx=clamp(p.x+x*speed*dt,35,W-35),ny=clamp(p.y+y*speed*dt,48,H-42);if(!hitsObstacle(nx,p.y,p.r))p.x=nx;if(!hitsObstacle(p.x,ny,p.r))p.y=ny;p.attackCd=Math.max(0,p.attackCd-dt);p.dashCd=Math.max(0,p.dashCd-dt);p.invuln=Math.max(0,p.invuln-dt);p.trail.push({x:p.x,y:p.y,life:.2});p.trail=p.trail.filter(t=>(t.life-=dt)>0)}
